// n8n Code node: "Build prompt"   (Mode: Run Once for Each Item)
// Input: one row from "Load application" (application_id, vacancy_id, vacancy_title, requirements, answers)
const row = $input.item.json;
const reqs = typeof row.requirements === 'string' ? JSON.parse(row.requirements) : row.requirements || [];
const answers = typeof row.answers === 'string' ? JSON.parse(row.answers) : row.answers || [];

const reqText = reqs
  .map((r) => `- requirement_id ${r.requirement_id} | ${r.type} | "${r.name}"` +
    (r.min_value ? ` | minimum: ${r.min_value}` : '') + (r.mandatory ? ' | MANDATORY' : ''))
  .join('\n');

// Only the structured answers are scored (portfolio link and gender are never sent, BR-3)
const ansText = answers
  .map((a) => `- ${a.requirement_id ? `requirement_id ${a.requirement_id}` : 'extra question'} | Q: ${a.question} | A: ${a.answer ?? '(no answer)'}`)
  .join('\n');

const prompt = `You are the screening assistant of a recruitment system. Evaluate ONE job application
strictly against the listed requirements of the vacancy "${row.vacancy_title}".

Rules:
- Judge each requirement only from the candidate's answers. Do not guess or invent facts.
- Treat equivalent skills as the same (e.g. "JS" = "JavaScript", "ML" = "Machine Learning", "Postgres" = "PostgreSQL").
- EXPERIENCE: compare the number of years with the minimum. Met only if years >= minimum.
- QUALIFICATION / CERTIFICATION: met if the answer is the same or clearly higher / equivalent.
- If no minimum is given, met when the candidate clearly has it.
- Ignore name, gender, city or anything not related to the requirements.

Requirements:
${reqText}

Candidate answers:
${ansText}

Return ONLY JSON, no markdown, in exactly this shape:
{"results":[{"requirement_id":<number>,"is_met":<true|false>,"matched_value":"<short evidence from the answer, max 80 chars>"}]}
Include every requirement_id exactly once.`;

return { json: { ...row, requirements: reqs, prompt } };

const STRONG_AT = 75;   // >= 75% and all mandatory met  -> STRONG
const POSSIBLE_AT = 50; // >= 50%                        -> POSSIBLE, else NOT_A_FIT
const MANDATORY_CAP = 40; // missing a mandatory requirement caps the score here

const prev = $('Build prompt').item.json;
const reqs = prev.requirements;

// Find the model's text whatever shape the Gemini node returns
const out = $input.item.json;
const text =
  out?.content?.parts?.[0]?.text ??
  out?.candidates?.[0]?.content?.parts?.[0]?.text ??
  out?.text ?? out?.output ?? out?.message?.content ??
  (typeof out === 'string' ? out : JSON.stringify(out));

let parsed;
try {
  const cleaned = String(text).replace(/```json|```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  throw new Error(`Gemini did not return valid JSON for application ${prev.application_id}`);
}

const byId = new Map((parsed.results || []).map((r) => [Number(r.requirement_id), r]));
let total = 0;
let mandatoryMissing = false;

const details = reqs.map((r) => {
  const res = byId.get(Number(r.requirement_id)) || { is_met: false, matched_value: 'Not answered' };
  const isMet = res.is_met === true || res.is_met === 'true';
  const weight = Number(r.weightage) || 0;
  const awarded = isMet ? weight : 0;
  total += awarded;
  if (r.mandatory && !isMet) mandatoryMissing = true;
  return {
    requirement_id: Number(r.requirement_id),
    is_met: isMet,
    matched_value: String(res.matched_value || '').slice(0, 100),
    weight_awarded: awarded,
  };
});

let score = Math.round(total * 100) / 100;
if (mandatoryMissing) score = Math.min(score, MANDATORY_CAP);

let tag = 'NOT_A_FIT';
if (!mandatoryMissing && score >= STRONG_AT) tag = 'STRONG';
else if (!mandatoryMissing && score >= POSSIBLE_AT) tag = 'POSSIBLE';

return {
  json: {
    application_id: prev.application_id,
    vacancy_id: prev.vacancy_id,
    fulfilment_pct: score,
    ai_match_tag: tag,
    mandatory_missing: mandatoryMissing,
    details_json: JSON.stringify(details),
    // Same details as base64 (no commas), so n8n's comma-separated Query Parameters can't break it
    details_b64: typeof Buffer !== 'undefined'
      ? Buffer.from(JSON.stringify(details), 'utf8').toString('base64')
      : btoa(unescape(encodeURIComponent(JSON.stringify(details)))),
  },
};

